CREATE POLICY "Tutoring students read visible kit block files" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'tutoring-materials' AND (storage.foldername(name))[1] = 'kits' AND EXISTS (SELECT 1 FROM public.tutoring_lesson_blocks b JOIN public.tutoring_lessons l ON l.id = b.lesson_id WHERE l.student_id = auth.uid() AND b.visible_to_student = true AND name IN (b.payload->>'image_path', b.payload->>'audio_path')));